android.extraProguardRules:
# Shoneya — règles R8 (optimisation du code, demandée par Google Play)
# Module natif des appels / notifications : appelé depuis le JS et par nom
-keep class expo.modules.shopicalls.** { *; }
# ShopiCallsMessagingService démarre React par réflexion (getReactHost / start)
-keep class * implements com.facebook.react.ReactApplication { *; }
-keep interface com.facebook.react.ReactHost { *; }
-keep class * implements com.facebook.react.ReactHost { public *; }
# Son et haut-parleur pendant les appels
-keep class com.zxcpoiu.incallmanager.** { *; }
# WebRTC (JNI) — déjà gardé par la bibliothèque, répété par sécurité
-keep class org.webrtc.** { *; }
